'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/navrail/md-gb-nav-rail.js';
import '@material/web/labs/gb/components/navrail/md-gb-nav-rail-item.js';
import {NavRailElement} from '@material/web/labs/gb/components/navrail/nav-rail-element.js';
import {NavRailItemElement} from '@material/web/labs/gb/components/navrail/nav-rail-item-element.js';

/**
 * A Material Design navigation rail custom element. Wraps <md-gb-nav-rail>.
 * Docs: https://material-web.dev/3.0/components/navigation-rail/
 */
export const MdNavRail = createComponent({
  react: React,
  tagName: 'md-gb-nav-rail',
  elementClass: NavRailElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onToggle: 'toggle' as EventName<CustomEvent<{expanded: boolean, reason?: string}>>,
  },
});

export type MdNavRailProps = React.ComponentProps<typeof MdNavRail>;

/**
 * A Material Design navigation rail item custom element. Wraps <md-gb-nav-rail-item>.
 * Docs: https://material-web.dev/3.0/components/navigation-rail/
 */
export const MdNavRailItem = createComponent({
  react: React,
  tagName: 'md-gb-nav-rail-item',
  elementClass: NavRailItemElement,
});

export type MdNavRailItemProps = React.ComponentProps<typeof MdNavRailItem>;
